def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    opp_budgets = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            opp_budgets.append(opp.get('budget', 0))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opps:
        if hp <= 2 or no_water_days >= 1:
            return min(budget, 50.0)
        return min(budget, 18.0)

    max_prev = max(prev_bids) if prev_bids else 0.0
    min_prev = min(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    richest_opp = max(opp_budgets) if opp_budgets else 0.0

    severe_need = hp <= 2 or no_water_days >= 2
    urgent_need = hp <= 4 or no_water_days >= 1

    if supply < WATER_REQ:
        if severe_need:
            bid = min(budget, max(58.0, max_prev + 3.0))
        else:
            bid = min(budget, 8.0)
        return max(0.0, bid)

    enough_for_one = supply < 2 * WATER_REQ

    if severe_need:
        target = max(62.0, min(0.92 * DAILY_SALARY, max_prev + 4.0))
        if budget < target:
            target = budget
        return max(0.0, min(budget, target))

    if enough_for_one:
        if max_prev >= 160:
            if hp >= 7 and no_water_days == 0 and day <= 7:
                bid = 16.0
            elif urgent_need:
                bid = min(budget, max(66.0, min(max_prev + 2.0, 0.95 * DAILY_SALARY)))
            else:
                bid = 24.0
        elif max_prev >= 100:
            if urgent_need:
                bid = min(budget, max(58.0, max_prev + 2.0))
            else:
                bid = min(budget, max(32.0, avg_prev * 0.55))
        else:
            bid = 40.0 if urgent_need else 22.0
    else:
        if urgent_need:
            bid = min(budget, max(48.0, min_prev + 2.0 if prev_bids else 48.0))
        else:
            bid = min(budget, max(26.0, avg_prev * 0.35 if prev_bids else 26.0))

    if budget > richest_opp and urgent_need:
        bid = min(budget, bid + 4.0)

    if day >= 8:
        if hp >= 6 and no_water_days == 0:
            bid = min(budget, bid * 0.9)
        else:
            bid = min(budget, bid + 5.0)

    return max(0.0, min(budget, float(bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if budget <= 0:
        return 0.0

    # Extract yesterday bids from alive opponents (immediate reaction only)
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    # Estimate opponent pressure
    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Supply pressure: lower supply means more competition -> bid higher
    # supply is between 15 and 25
    supply_mid = (MIN_SUPPLY + MAX_SUPPLY) / 2.0
    supply_factor = 1.0
    if supply <= supply_mid:
        supply_factor = 1.15
    else:
        supply_factor = 0.95

    # Our urgency: low HP or many no-water days => bid much higher
    urgency = 1.0
    if hp <= 2:
        urgency = 1.35
    elif hp <= 4:
        urgency = 1.20
    elif no_water_days >= 2:
        urgency = 1.15

    # Target bid baseline derived from yesterday's best signal
    # If someone bid extremely high yesterday, match pressure to avoid being outbid.
    if highest_prev >= DAILY_SALARY * 1.8:
        base = max(highest_prev * 0.75, DAILY_SALARY * 0.95)
    elif avg_prev > DAILY_SALARY * 1.2:
        base = max(avg_prev * 0.65, DAILY_SALARY * 0.75)
    else:
        base = max(DAILY_SALARY * 0.6, highest_prev * 0.55)

    # Apply factors and cap by budget
    bid = base * supply_factor * urgency

    # Keep some budget for later; but if we are in danger, spend more.
    if hp <= 2 or no_water_days >= 3:
        budget_cap = budget * 0.95
    elif hp <= 4 or no_water_days >= 2:
        budget_cap = budget * 0.85
    else:
        budget_cap = budget * 0.75

    bid = min(bid, budget_cap, budget)

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

